import{_ as o,a0 as s,w as l,s as d,ao as u,I as n,x as t,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"如何在Ubuntu 14.04 LTS上安装MariaDB | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu 14.04 LTS上安装MariaDB | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu 14.04 LTS上安装MariaDB | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu 14.04 LTS上安装MariaDB | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141029 How to Install MariaDB in Ubuntu 14.04 LTS","title":"如何在Ubuntu 14.04 LTS上安装MariaDB","tag":"201411","desc":""},"relativePath":"201411/20141029 How to Install MariaDB in Ubuntu 14.04 LTS.md","filePath":"[post].md"}'),p={name:"201411/20141029 How to Install MariaDB in Ubuntu 14.04 LTS.md"};function m(b,a,M,h,D,T){const r=s("Link");return l(),d("div",null,[a[13]||(a[13]=u(`<h1 id="如何在ubuntu-14-04-lts上安装mariadb" tabindex="-1">如何在Ubuntu 14.04 LTS上安装MariaDB <a class="header-anchor" href="#如何在ubuntu-14-04-lts上安装mariadb" aria-label="Permalink to “如何在Ubuntu 14.04 LTS上安装MariaDB”">​</a></h1><p>MariaDB是一个开源数据库且100%与MySQL兼容，目标是替代MySQL数据库。</p><h3 id="mariadb的背景" tabindex="-1">MariaDB的背景 : <a class="header-anchor" href="#mariadb的背景" aria-label="Permalink to “MariaDB的背景 :”">​</a></h3><p>2008年，MySQL被后来被Oracle在2010年收购的<strong>Sun Microsystems</strong>收购了。 最初被Sun公司的收购由于符合项目的需要而受到MySQL社区的欢呼，但是这种情绪并没有持续太久，接下来被Oracle的收购，不幸期望远远低于预期。许多MySql的开发者离开了Sun和Oracle公司开始新的项目。在他们中间就有MySQL的创建者以及项目长期技术带头人之一的<strong>Michael ‘Monty’ Widenius</strong>。Monty和他的团队创建了MySQL的一个fork版本并且命名它为<strong>MariaDB</strong>。</p><p>本篇我们会讨论如何在Ubuntu上安装MariaDB。默认上MariaDB的包并没有在Ubuntu仓库中。要安装MariaDB，我们首先要设置MariaDB仓库。</p><h4 id="设置-mariadb-仓库" tabindex="-1">设置 MariaDB 仓库 <a class="header-anchor" href="#设置-mariadb-仓库" aria-label="Permalink to “设置 MariaDB 仓库”">​</a></h4><pre><code>$ sudo apt-get install software-properties-common
$ sudo apt-key adv --recv-keys --keyserver hkp://keyserver.ubuntu.com:80 0xcbcb082a1bb943db
$ sudo add-apt-repository &#39;deb http://sfo1.mirrors.digitalocean.com/mariadb/repo/10.0/ubuntu trusty main&#39;
</code></pre><h4 id="安装-mariadb" tabindex="-1">安装 MariaDB : <a class="header-anchor" href="#安装-mariadb" aria-label="Permalink to “安装 MariaDB :”">​</a></h4><pre><code>$ sudo apt-get update
$ sudo apt-get install mariadb-server
</code></pre><p>在安装中，你会被要求设置MariaDB的root密码。</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2014/10/mariadb-root-1024x442-1.jpg" alt=""></p><h4 id="从命令行连接到mariadb" tabindex="-1">从命令行连接到MariaDB : <a class="header-anchor" href="#从命令行连接到mariadb" aria-label="Permalink to “从命令行连接到MariaDB :”">​</a></h4><pre><code>linuxtechi@mail:~$ mysql -uroot -p
Enter password: 
Welcome to the MariaDB monitor.  Commands end with ; or \\g.
Your MariaDB connection id is 40
Server version: 10.0.14-MariaDB-1~trusty-log mariadb.org binary distribution
Copyright (c) 2000, 2014, Oracle, SkySQL Ab and others.
Type &#39;help;&#39; or &#39;\\h&#39; for help. Type &#39;\\c&#39; to clear the current input statement.
MariaDB [(none)]&gt;
</code></pre><h4 id="maria-db-服务" tabindex="-1">Maria DB 服务 <a class="header-anchor" href="#maria-db-服务" aria-label="Permalink to “Maria DB 服务”">​</a></h4><pre><code>$ sudo /etc/init.d/mysql stop
$ sudo /etc/init.d/mysql start
</code></pre><hr>`,16)),n("p",null,[a[1]||(a[1]=t("via: ",-1)),e(r,{href:"http://www.linuxtechi.com/install-mariadb-in-ubuntu/"},{default:i(()=>[...a[0]||(a[0]=[t("http://www.linuxtechi.com/install-mariadb-in-ubuntu/",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=t("作者：",-1)),e(r,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:i(()=>[...a[2]||(a[2]=[t("Pradeep Kumar",-1)])]),_:1}),a[6]||(a[6]=t(" 译者：",-1)),e(r,{href:"https://github.com/geekpi"},{default:i(()=>[...a[3]||(a[3]=[t("geekpi",-1)])]),_:1}),a[7]||(a[7]=t(" 校对：",-1)),e(r,{href:"https://github.com/wxy"},{default:i(()=>[...a[4]||(a[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=t("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[8]||(a[8]=[t("LCTT",-1)])]),_:1}),a[11]||(a[11]=t(" 原创翻译，",-1)),e(r,{href:"http://linux.cn/"},{default:i(()=>[...a[9]||(a[9]=[t("Linux中国",-1)])]),_:1}),a[12]||(a[12]=t(" 荣誉推出",-1))])])}const c=o(p,[["render",m]]);export{S as __pageData,c as default};
